    "lifeStory": "惠能大师，俗姓卢，岭南新州（今广东新兴）人。三岁丧父，与母孤苦相依，樵采供养。一日负柴入市，闻客诵《金刚经》至\u201c应无所住而生其心\u201d，言下心开，遂问经从何来，客言黄梅五祖弘忍大师处。惠能安顿老母，跋涉三十余日至黄梅，弘忍问：\u201c汝何方人？欲求何物？\u201d答曰：\u201c弟子是岭南新州百姓，唯求作佛，不求余物。\u201d弘忍曰：\u201c汝是岭南人，又是獦獠，若为堪作佛？\u201d惠能曰：\u201c人虽有南北，佛性本无南北，獦獠身与和尚不同，佛性有何差别？\u201d弘忍知其根器，令入碓坊踏碓。\n\n八月余后，弘忍密召入室，为说《金刚经》，至\u201c应无所住而生其心\u201d，惠能言下大悟，连呼五个\u201c何期\u201d：\u201c何期自性本自清净！何期自性本不生灭！何期自性本自具足！何期自性本无动摇！何期自性能生万法！\u201d遂受衣钵，为第六祖，时年二十四。南归隐遁四会猎人队十五年，后于广州法性寺值印宗法师讲《涅槃经》，闻二僧争论风动幡动，惠能进曰：\u201c不是风动，不是幡动，仁者心动。\u201d一语惊四座，印宗为之剃度，请说东山法门。次年还曹溪宝林寺，大阐顿悟宗旨，学徒万余，嗣法弟子四十三人，着《六祖法宝坛经》——中国祖师著作唯一称\u201c经\u201d者。先天二年（713年）示寂于新州国恩寺，肉身至今供奉于南华寺。",
    "teachings": "惠能以\u201c无念为宗，无相为体，无住为本\u201d立宗：于诸境上心不染曰无念，于相而离相曰无相，于诸法上念念不住曰无住。又倡定慧一体——定是慧体，慧是定用，犹如灯光，有灯即光，无灯即暗。其顿悟教直指：前念迷即凡夫，后念悟即佛；菩提自性，本来清净，但用此心，直了成佛。自此禅宗一洗渐次之繁，直指之教风行天下，后世五家七宗皆出曹溪。",
    "quotes": [
      "菩提本无树，明镜亦非台。本来无一物，何处惹尘埃。",
      "何期自性本自清净！何期自性本不生灭！何期自性本自具足！何期自性本无动摇！何期自性能生万法！",
      "不是风动，不是幡动，仁者心动。",
      "迷闻经累劫，悟则刹那间。 —《六祖坛经》"
    ],
    "classics": [
      "六祖法宝坛经"
    ],
