    "id": "huangbo",
    "name": "黄檗希运",
    "title": "传心法要祖师",
    "era": "唐代 (?-850)",
    "lifeStory": "希运禅师，闽人，幼于本州黄檗山出家，额间隆起如肉珠，音辞朗润，性志冲漠。初参百丈怀海，丈问：\u201c巍巍堂堂从何方来？\u201d师曰：\u201c巍巍堂堂从岭南来。\u201d丈曰：\u201c巍巍堂堂当为何事？\u201d师曰：\u201c巍巍堂堂不为别事。\u201d便礼拜。后随百丈入山作务，一日百丈问：\u201c什么处去来？\u201d师曰：\u201c大雄山下采菌子来。\u201d丈曰：\u201c还见大虫么？\u201d师便作虎啸，丈拈斧作斫势，师即掴丈一掴，丈吟吟而笑便归，上堂谓众曰：\u201c大雄山下有一大虫，汝等诸人也须好看，百丈老汉今日亲遭一口。\u201d\n\n裴休相国镇宛陵时，迎请希运至开元寺说法，亲为记录，是为《黄檗山断际禅师传心法要》及《宛陵录》。师教风峻烈，常以棒喝接人：临济义玄三度问\u201c如何是佛法的大意\u201d，三度被打，后于大愚座下豁然大悟，归来自言\u201c原来黄檗佛法无多子\u201d，遂开临济一宗，门庭施设最为峻烈。希运所倡\u201c即心是佛，无心是道\u201d，谓诸佛与一切众生唯是一心，更无别法；但能无心，便是究竟。大中四年（850年）示寂，谥\u201c断际禅师\u201d。",
    "teachings": "希运之学，唯传一心：此心即是佛，佛即是众生；为众生时此心不减，为诸佛时此心不添。乃至六度万行，河沙功德，本来自足，不假修添。其破执尤力：才作佛见，便被佛障；才作众生见，便被众生障。但于见闻觉知处认本心，然本心不属见闻觉知，亦不离见闻觉知——不即不离，不住不着，纵横自在，无非道场。",
