    "id": "dongshan",
    "name": "洞山良价",
    "title": "曹洞宗开山祖师",
    "era": "唐代 (807-869)",
    "lifeStory": "良价禅师，会稽诸暨（今浙江诸暨）人，俗姓俞。幼岁依村院出家，一日读《心经》至\u201c无眼耳鼻舌身意\u201d处，以手扪面问师曰：\u201c某甲有眼耳鼻舌等，何故经言无？\u201d其师骇然曰：\u201c吾非汝师。\u201d遂指往五泄山礼灵默禅师披剃，二十一岁诣嵩山受具。\n\n后行脚参方：首参南泉普愿，值南泉设斋问：\u201c昨日设斋，不知马大师还来也无？\u201d众皆无对，师出曰：\u201c待有伴即来。\u201d南泉曰：\u201c此子虽后生，甚堪雕琢。\u201d又参沩山灵祐，问：\u201c顷闻南阳忠国师有无情说法话，某甲未究其微。\u201d沩山曰：\u201c阇黎莫记得么？\u201d师曰：\u201c记得。\u201d举似了，沩山曰：\u201c汝试举一遍看。\u201d师举讫，问：\u201c无情说法，什么人得闻？\u201d沩山曰：\u201c无情得闻。\u201d师曰：\u201c和尚还闻否？\u201d沩山曰：\u201c我若闻，汝即不闻吾说法也。\u201d师犹未透，沩山指往云岩昙晟处。\n\n至云岩，师问：\u201c无情说法，什么人得闻？\u201d云岩曰：\u201c无情得闻。\u201d师曰：\u201c和尚还闻否？\u201d云岩曰：\u201c我若闻，汝即不得见吾也。\u201d师曰：\u201c恁么则良价不闻和尚说法也。\u201d云岩曰：\u201c我说法汝尚不闻，岂况无情说法乎？\u201d师曰：\u201c无情说法，该何典教？\u201d云岩曰：\u201c岂不见《弥陀经》云：水鸟树林悉皆念佛念法。\u201d师于言下有省，乃述偈曰：\u201c也大奇，也大奇，无情说法不思议。若将耳听终难会，眼处闻声方得知。\u201d\n\n后辞云岩，过水睹影，豁然大悟，偈曰：\u201c切忌从他觅，迢迢与我疏。我今独自往，处处得逢渠。渠今正是我，我今不是渠。应须恁么会，方得契如如。\u201d遂嗣云岩之法，住豫章洞山（今江西宜丰），倡\u201c五位君臣\u201d——正中偏、偏中正、正中来、偏中至、兼中到，以绵密细致的宗风接人，与弟子曹山本寂共开曹洞一宗，与临济并称于世。咸通十年（869年）示寂，世寿六十三，谥\u201c悟本禅师\u201d。",
    "teachings": "良价之教，贵回互、尚绵密：正偏回互，君臣道合，于偏正五位中明体用一如之旨。其宗风不似临济之雷霆棒喝，而如暗室织锦，针脚细密——\u201c银碗盛雪，明月藏鹭\u201d，令学人在不知不觉中脱落情见。曹洞一宗后传至日本，为道元希觉所承，至今为日本禅宗两大主流之一。",
    "quotes": [
      "切忌从他觅，迢迢与我疏。我今独自往，处处得逢渠。 —过水睹影悟道偈",
      "也大奇，也大奇，无情说法不思议。若将耳听终难会，眼处闻声方得知。",
      "渠今正是我，我今不是渠。应须恁么会，方得契如如。"
    ],
