    "lifeStory": "行思禅师，吉州庐陵（今江西吉安）人，俗姓刘。少年出家，后参六祖惠能，为六祖门上首弟子。六祖问：\u201c汝作什么来？\u201d师曰：\u201c圣谛亦不为。\u201d祖曰：\u201c落何阶级？\u201d师曰：\u201c圣谛尚不为，何阶级之有？\u201d六祖深器之，命居首座。后住吉州青原山静居寺，大弘禅法，门下出石头希迁，石头门下又出药山、天皇、丹霞等，开曹洞、云门、法眼三宗，与南岳怀让系并称禅宗两大主流。",
