    "lifeStory": "慈明楚圆禅师（986—1039），全州清湘人，俗姓李。少业儒，二十二岁出家，与大愚、谷泉、琅琊结伴同参汾阳善昭禅师，得其心印，为临济宗第七世。历住袁州南源、潭州道吾、石霜诸刹，赐号\u201c慈明\u201d。平生真率作事、为法忘躯：河东苦寒，众人惮行，师志在于道，晓夕不怠，夜坐欲睡则引锥自刺。门下出黄龙慧南、杨岐方会两大宗匠，临济宗由此分为黄龙、杨岐二派，杨岐一系绵延至今，师实为宋代以后临济正脉之总源。《禅林宝训》屡载其德业苦节，以为后世住持楷模。",
