    "lifeStory": "云门文偃禅师，姑苏嘉兴（今浙江嘉兴）人，俗姓张。幼年依空王寺志澄律师出家，资质聪颖，博通内外典籍。后参睦州陈尊宿，每往参问，陈尊宿皆闭门不纳；一日师扣门，陈尊宿开门一见便闭，师于门缝间挤断一足，当下大悟。陈尊宿指示往参雪峰义存，师于雪峰会下契悟宗旨，充任首座。后住韶州云门山光泰禅院，以\u201c云门三句\u201d——函盖乾坤句、截断众流句、随波逐浪句——为宗门施设，一言半语即截断学人情识，所谓\u201c云门一字关\u201d。其接人机锋险绝，如\u201c干屎橛\u201d\u201c日日是好日\u201d等语，言简意赅而意趣深远。门人守坚集其语录为《云门匡真禅师广录》。云门宗风行五代至北宋，与临济、曹洞并称禅门三大宗。",
