    "teachings": "廓庵十牛图以牛喻心，以牧童喻修行者：寻牛即发心修道，见迹即解悟教理，见牛即初见本性，得牛即契悟宗旨，牧牛即保任磨炼，骑牛归家即悟后起修，忘牛存人即能所双泯，人牛俱忘即法执亦遣，返本还源即归无所得，入廛垂手即和光同尘、广度众生。十图层层递进，将禅宗修行次第圆满呈现。",
