    "lifeStory": "黄庭坚，字鲁直，号山谷道人，洪州分宁（今江西修水）人。北宋四大书法家之一，与苏轼齐名，世称\u201c苏黄\u201d。师虽为文坛宗匠，然深契禅宗宗旨，参黄龙晦堂祖心，与灵源惟清交游甚密。师以诗文入禅，以书法悟道，为北宋\u201c士大夫禅\u201d之典范。晦堂曾以\u201c吾无隐乎尔\u201d开示黄庭坚，师闻之豁然有省——此即著名之\u201c木樨香\u201d公案：晦堂曰：\u201c闻木樨香么？\u201d师曰：\u201c闻。\u201d晦堂曰：\u201c吾无隐乎尔。\u201d师于言下大悟。",
