    "lifeStory": "隆琦禅师，福建福清人，俗姓林。少出家，参费隐通容，于通容座下开悟。师住黄檗山（今福建福清），大弘临济宗风。清顺治十一年（1654年），师应日本长崎华侨之请东渡，后住京都宇治，开创万福寺，建立日本黄檗宗——为日本禅宗三大宗（临济、曹洞、黄檗）之一。师之教承临济\u201c棒喝\u201d之传统，兼融念佛与参禅，为明清禅净合流之重要传人。师又传明代文化于日本，包括书法、绘画、建筑、茶道等，对日本文化影响深远。",
