    "teachings": "佛印之教，以诗文入禅，于文采中显禅机。其与苏轼之交往，为禅宗与文人结合之典范，示禅宗\u201c道在日用\u201d之旨。",
    "quotes": ["一切有为法，如梦幻泡影。"],
