    "lifeStory": "开福道宁禅师，徽州绩溪（今安徽绩溪）人，俗姓汪。初为道人，后在金陵蒋山依雪窦老良禅师落发。师先在崇果寺充当浴头，一日洗足间偶诵《金刚经》，至\u201c于此章句能生信心，以此为实\u201d忽然身心双忘，发明心地。后遍历丛林，参五祖法演，闻举忠国师古佛净瓶、赵州狗子无佛性等公案，顿彻法源，得法演印可。大观三年（1109），潭州地方官席震请师住开福禅寺（今湖南长沙），衲子云集，众盈五百。师住开福五年，政和三年（1113）示寂。着有《开福宁禅师语录》二卷。嗣法弟子月庵善果，法脉递传老衲祖证、月林师观、无门慧开，至日本僧法灯觉心——觉心回国创法灯派，日本临济宗视开福寺为祖庭。",
    "teachings": "开福宗风承五祖\u201c逼拶\u201d之旨，一柱杖划断古今葛藤，一拂子指开大千障碍。师示众云：\u201c遍界不曾藏，通身无影像。相逢莫讶太愚痴，旷劫至今无伎俩。\u201d又云：\u201c大道无私要由心悟，心无形状全物而彰。\u201d其教行住坐卧无非妙用，语默动静悉为佛事。",
