    "era": "北宋",
    "lifeStory": "长芦宗赣（生卒不详），北宋禅僧，住持真州长芦寺。宗赣禅师以精严著称，重规立制，撰《坐禅仪》一文，系统阐述坐禅之威仪、调身、调息、调心之法，为后世坐禅之圭沅。其《坐禅仪》承天台止观与圭峰宗密《修证仪》之统，而归宗于禅门\u201c一切善恶都莫思量\u201d之无心要旨。宗赣禅师又制《禅苑清规》，为禅门规式之集大成者，对后世丛林制度影响深远。",
