    "title": "马祖法嗣 / 犀牛扇子公案主人",
    "era": "唐代 (约750-842)",
    "lifeStory": "盐官齐安禅师，马祖道一法嗣，住杭州盐官（今浙江海宁），世称盐官齐安。曾因犀牛扇子公案闻名：《碧岩录》第九十一则载，师问侍者犀牛扇子何在，侍者无言，师示偈云犀牛扇子用多时，问著元来总不知。其机用绵密，接人平实，是马祖门下重要传人之一。",
