    "era": "唐代 (635-730)",
    "lifeStory": "李通玄，世称枣柏大士，唐代华严宗居士学者。唐皇室宗族，居五台山方山，研习《华严经》数十年。著有《新华严经论》四十卷、《华严经决疑论》等，以《易经》释《华严》，融通儒佛，自成一家。其论为后世禅宗所重，惠洪觉范为之作像赞。",
