    "name": "宝志",
    "title": "宝志禅师",
    "era": "南朝 (418-514)",
    "lifeStory": "宝志，又称宝志公、志公和尚，南朝梁代神异僧。金城人，少出家于道林寺，修习禅定。常跣足行于街巷，言行神异，预言多验。梁武帝深为敬信，迎入华林园。世传为观世音菩萨化身。其\u201c剪刀裁衣、杖头挂帽\u201d之风流放旷，为后世禅宗所传颂。",
    "teachings": "以神异方便示现，不立文字，直指人心。",
