    "title": "击竹悟道禅师",
    "era": "唐代 (?-898)",
    "lifeStory": "香严智闲，唐代禅僧，沩山灵祐弟子。初在百丈门下参学，后参沩山，因沩山问\u201c父母未生时面目\u201d而茫然，遂辞去。后于南阳慧忠国师遗址居止，一日芟除草木，掷瓦击竹作声，豁然顿悟。悟后作偈曰\u201c一击忘所知，更不假修治\u201d。世称香严击竹，为禅宗著名公案。不立文字，直指心源。",
