    "lifeStory": "丹霞天然，唐代禅僧。初欲选官，遇禅客劝令选佛，遂往参石头希迁、马祖道一。于慧林寺遇天寒，取木佛烧火取暖，院主呵之，师曰\u201c吾烧取舍利\u201d，院主曰\u201c木佛何有舍利\u201d，师曰\u201c既无舍利，更取两尊来烧\u201d。其狂放不羁，不拘规矩，为禅宗破执之典范。",
