    "category": "心法",
    "summary": "不立文字，教外别传——禅宗标榜的传法方式：第一义谛超越语言文字，如人饮水，冷暖自知，不可向人道。《楞伽经》云\u201c佛语心为宗\u201d，《金刚经》云\u201c如来所说法，皆不可取，不可说\u201d。然禅宗\u201c不立\u201d文字，并非\u201c不用\u201d文字：达摩以《楞伽》印心，六祖因《金刚》开悟，历代祖师语录汗牛充栋——文字如指月之指，病在认指为月，不在指本身。故禅门以言遣言、以楔出楔，机锋转语皆是\u201c活句\u201d：不堕义解，直下截断思量，令人于言外见性。",
