    "summary": "以诗偈形式对古则公案进行吟咏评赞。颂古非解释公案，乃以诗境暗示悟境——言在意外，意在言外。无门慧开《无门关》每则公案后皆附颂古四句，以诗偈浓缩公案意境，启发学人悟境。颂古与评唱互补：评唱是理性引导，颂古是直觉启发。",
