    "summary": "话头有句意二门。参句者，径截门，活句也——没心路没语路无摸索故。参意者，圆顿门，死句也——有理路有语路有闻解思相故。活句下荐得堪与佛祖为师，死句下荐得自救不了。此为退隐禅师《禅家龟鉴》所倡参禅要旨。",
    "etymology": "活句者，无理路可循之言句，逼拶学人至思量不及处；死句者，有理路可解之言句，学人落于知解。此说源于禅宗参活句不参死句之传统。",
