    "id": "jianxing-chengfo",    "title": "见性成佛",    "category": "禅法",    "summary": "见性成佛，禅宗根本宗旨：直指人心，见性成佛。见性者，彻见自家本具之佛性——非修得、非造作、非从外得，本来现成；见则当下是佛，不见则轮回六趣。达摩西来，唯传此一心之旨；六祖闻\u201c应无所住而生其心\u201d言下大悟，即是见性榜样。见性非见一物、得一境——性无相状，见无所见，彻悟本来清净心，即是见性。",    "etymology": "见性（彻见本具佛性）+ 成佛（圆满觉证），直指人心之宗旨。",    "quotes": ["直指人心，见性成佛。 —达摩西来宗旨"],    "guidance": "莫将见性作见光见华、得特殊体验会——凡有所见皆非。性在作用：见色闻声、扬眉瞬目的是谁？于此参究，蓦地彻见能见之性本空本净，是名见性。见性之后尚须保任，非一悟便了。",    "classicRef": "《血脉论》《六祖坛经》",    "relatedConcepts": ["buddha-nature", "direct-pointing", "self-nature"],    "relatedPersons": ["bodhidharma", "huineng"],    "relatedBooks": ["xuemaicong", "tanjing"]
