    "id": "chanyuan",    "title": "禅源",    "category": "禅法",    "summary": "禅源，宗密立名：禅是天竺之语禅那，翻为思惟修、静虑，为定慧通称；源是一切众生本觉真性，亦名佛性、心地。此性是禅之本源，故名禅源。宗密辨之：非离真性别有禅体——迷真合尘名散乱，背尘合真名禅定；直论本性则非真非妄、无背无合、无定无乱。一源多名：万法之源名法性，迷悟之源名如来藏藏识，万德之源名佛性，万行之源名心地。",    "etymology": "禅（禅那、定慧）+ 源（本源、真性），禅之本源即众生本觉真性。",    "quotes": ["源者，是一切众生本觉真性，亦名佛性，亦名心地。 —宗密《禅源诸诠集都序》"],    "guidance": "修行先识源：一切禅定智慧皆从本觉真性流出，莫离源觅流、抛家宝行乞。见一切法门同出一源，则诸宗纷诤自然平息——此\"会归禅源\"之读法。",    "classicRef": "《禅源诸诠集都序》卷上",    "relatedConcepts": ["self-nature", "buddha-nature", "rulai-qingjing-chan"],    "relatedPersons": ["guifeng-zongmi"],    "relatedBooks": ["chanyuan_zhuquanjiduxu"]
