    "id": "rulai-qingjing-chan",    "title": "如来清净禅（最上乘禅）",    "category": "禅法",    "summary": "宗密判禅为五种：带异计欣上厌下而修者外道禅；正信因果亦以欣厌而修者凡夫禅；悟我空偏真之理者小乘禅；悟我法二空所显真理者大乘禅。最上乘禅者——顿悟自心本来清净、元无烦恼、无漏智性本自具足、此心即佛毕竟无异，依此而修，亦名如来清净禅、一行三昧、真如三昧，是一切三昧根本，念念修习自然渐得百千三昧。达摩门下展转相传者正是此禅；达摩未到之前，此土诸家所修皆前四类禅定。",    "etymology": "如来（如实而来）+ 清净（离诸染污）+ 禅，顿悟本心直依佛性而修之禅。",    "quotes": ["若顿悟自心本来清净，元无烦恼，无漏智性，本自具足，此心即佛，毕竟无异，依此而修者，是最上乘禅。 —宗密"],    "guidance": "五禅之判是照妖镜：修行人所修到底是外道禅（带着邪见与欣厌）还是凡夫禅（只为福报）？唯有安住本具清净心而修，方名最上乘。检验不在打坐姿势，在见地与用心。",    "classicRef": "《禅源诸诠集都序》卷上·五种禅",    "relatedConcepts": ["chanyuan", "yixing-sanmei", "mind-is-buddha"],    "relatedPersons": ["guifeng-zongmi", "bodhidharma"],    "relatedBooks": ["chanyuan_zhuquanjiduxu"]
