    "id": "lingzhi",    "title": "灵知",    "category": "心性",    "summary": "灵知，宗密承接荷泽而言者：空寂之心，灵知不昧——即此空寂之知是汝真性。此知非缘境分别之识，非证体了达之智，直是真如自性自然常知；任迷任悟，心本自知，不藉缘生，不因境起，故曰知之一字，众妙之门。宗密以水为喻：湿是水之体，知是心之体——知之一字，贯于贪嗔慈忍、善恶苦乐万用万义之处。迷之则妄执身心为我，悟之则念起即觉、觉之即无。",    "etymology": "灵（灵妙不昧）+ 知（本自知照），真如自性自然常知之谓，非分别之识。",    "quotes": ["空寂之心，灵知不昧。即此空寂之知，是汝真性。", "知之一字，众妙之门。 —荷泽神会/宗密"],    "guidance": "辨知与识：缘境分别、睡时便断的是识；不待缘发、迷悟恒然的是灵知。参\"念佛是谁\"正要于此能知背后勘落识尘。切忌把\"灵知\"又变成一个玄妙境界去把捉——知是心之体，不是心中一物。",    "classicRef": "《禅源诸诠集都序》卷中·直显心性宗",    "relatedConcepts": ["shishen", "self-nature", "real-mind"],    "relatedPersons": ["guifeng-zongmi", "shenhui"],    "relatedBooks": ["chanyuan_zhuquanjiduxu"]
