    "id": "chanyiao-yizhi",    "title": "禅教一致",    "category": "禅宗判摄",    "summary": "禅教一致，宗密全部著作之根本主张：经是佛语，禅是佛意，诸佛心口必不相违。当时讲者偏彰渐义、禅者偏播顿宗，禅讲相逢如胡越之隔；修心者以经论为别宗，讲说者以禅门为别法。宗密出而和会：以三种教印三宗，禅教双资——以教照心，以心解教；须识禅心性相方解经论理事，须知经论权实方辨诸禅是非。会通之后禅教双忘、心佛俱寂——俱寂则念念皆佛，双忘则句句皆禅。",    "etymology": "禅（佛意）+ 教（佛语）+ 一致（心口不二），宗密判教之根本立场。",    "quotes": ["经是佛语，禅是佛意，诸佛心口必不相违。 —宗密", "执则字字疮疣，通则文文妙药。"],    "guidance": "今人学佛亦分两党：只读经论的说禅是空谈，只参禅的说教是葛藤。宗密之判是良药：教无禅则说食数宝，禅无教则盲修瞎练——如绳墨与工巧，如斗称与货物，相资为用。学一边者当自省。",    "classicRef": "《禅源诸诠集都序》全卷",    "relatedConcepts": ["sanzong", "sanjiao", "dunwu-jianxiu"],    "relatedPersons": ["guifeng-zongmi", "peixiu"],    "relatedBooks": ["chanyuan_zhuquanjiduxu"]
