    "summary": "棒喝交参，临济宗接引学人之峻烈方便。棒者，宗师以棒打学人，截断其意识流；喝者，宗师以大喝震慑学人，令其思量顿断。临济义玄之棒、德山宣鉴之棒、黄檗希运之喝，皆为禅宗最著名之棒喝。临济四料简——夺人不夺境、夺境不夺人、人境俱夺、人境俱不夺——皆以棒喝施设。棒喝非嗔怒打骂，乃大宗师为破学人执着而施设之\u201c格外方便\u201d——如良医以毒攻毒，以峻烈手段令学人于思量不及处亲见本来。",
