    "id": "koan-11",
    "question": "拈花微笑",
    "answer": "吾有正法眼藏，涅槃妙心，实相无相，微妙法门，不立文字，教外别传，付嘱摩诃迦叶。",
    "context": "灵山会上，世尊拈花示众。是时众皆默然，唯迦叶尊者破颜微笑。世尊曰：\u201c吾有正法眼藏，涅槃妙心，实相无相，微妙法门，不立文字，教外别传，付嘱摩诃迦叶。\u201d——此即禅宗\u201c教外别传\u201d的源头：不依经教文字，以心印心。自此迦叶为西天初祖，代代相传，至第二十八祖菩提达摩，泛海东来，为东土初祖；又六传至曹溪惠能，一花开五叶，禅宗遂遍于天下。",
    "interpretation": "拈花与微笑之间，没有一言半句，而法已传了——这是禅宗最根本的宣言：第一义谛不在文字语言里，只在心心相印处。百万人天不是不见花，是只见花而不见心；迦叶微笑，不是会得什么道理，是与世尊同一鼻孔出气——以本觉印本觉，如两镜相照，光光互摄。后世禅宗一切施设——棒喝机锋、看话默照——皆从这一拈一笑流出：教外别传，不立文字，直指人心，见性成佛。学者须于言句不及处体取：你自家的那一朵花，拈起了么？",
