    "answer": "大好山。",
    "context": "僧问天皇道悟禅师：\u201c如何是道？\u201d师曰：\u201c大好山。\u201d僧曰：\u201c学人道，何得好山？\u201d师曰：\u201c汝何不问道何得好山？\u201d",
