    "interpretation": "云门之\u201c春来草自青\u201d——春天到来，草自然青。佛法大意不在造作中——如春来草青，不假造作，自然现前。草不须努力变青——春至则青；心不须努力成佛——悟则成佛。此为禅宗\u201c自然\u201d之极致——道法自然，不假功用。",
