    "question": "如何是佛？",
    "answer": "麻三斤。",
    "context": "僧问洞山良价禅师：\u201c如何是佛？\u201d师曰：\u201c麻三斤。\u201d",
    "interpretation": "洞山之\u201c麻三斤\u201d——此语全无道理可讲。麻三斤与佛何干？正因无道理，方能截断学人一切思量分别。学人问佛，心中必有一佛相；洞山以\u201c麻三斤\u201d答之，令其佛相顿破。麻三斤者，非麻三斤，是名麻三斤——当下一念不生，麻三斤即是佛。此为洞山宗\u201c敲唱俱行\u201d之典型——以不相干之语，截断意识流。",
    "master": "洞山良价",
