    "question": "沩山踢瓶",
    "answer": "踢倒净瓶。",
    "context": "沩山灵祐禅师为百丈怀海之弟子。百丈一日令沩山拨净瓶，沩山不动手，以脚踢倒净瓶。百丈笑曰：\u201c这汉子如痴如醉。\u201d",
    "interpretation": "百丈令沩山拨净瓶——此为勘验学人之机。拨净瓶者，以手扶正净瓶——此为常人之行。沩山不动手，以脚踢倒——以反常之行截断百丈之勘验。百丈笑曰\u201c如痴如醉\u201d——非真笑其痴醉，乃印可其行：不为常理所拘，敢于打破常规。此为沩山宗风之雏形——温润中含峻烈，平常中含反常。",
