    "interpretation": "杨岐之\u201c春日春山里春明春草鲜\u201d——春日春山，春明春草——一切皆春，一切皆自然。祖师西来意不在别处，即此春日春山之自然。春来草自青——不假造作，自然现前。杨岐宗风以\u201c自然\u201d为旨——不以造作求道，因缘时至，自然悟道。此与云门\u201c春来草自青\u201d异曲同工。",
