    "id": "koan-163",
    "question": "如何是见性成佛？",
    "answer": "见自本性，即名为佛。",
    "context": "僧问六祖慧能：\u201c如何是见性成佛？\u201d师曰：\u201c见自本性，即名为佛。不悟即佛是众生，一念悟时众生是佛。\u201d",
    "interpretation": "六祖之\u201c见自本性即名为佛\u201d——见性者，见自本性；成佛者，即名为佛。佛非外得——见自本性即名为佛。不悟即佛是众生——自性本是佛，不悟即迷为众生；一念悟时众生是佛——一念顿悟，众生即佛。佛与众生之别，唯在迷悟——迷则佛是众生，悟则众生是佛。此为禅宗\u201c直指人心，见性成佛\u201d之根本教义。",
    "master": "六祖慧能",
    "source": "六祖坛经",
