    "context": "僧问赵州从谂禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c砖瓦将来。\u201d",
    "interpretation": "赵州之\u201c砖瓦将来\u201d——拿砖瓦来。学人问西来意，赵州以\u201c拿砖瓦来\u201d答之——西来意不在玄妙处，即此搬砖运瓦之平常。如庞蕴\u201c运水及搬柴\u201d——西来意在日用中，不在蒲团上。赵州以最平常之劳作示西来意——平常心是道，搬砖运瓦即是西来意之显现。",
