    "context": "僧问曹山本寂禅师：\u201c如何是祖师西来意？\u201d师曰：\u201c井中月。\u201d",
    "interpretation": "曹山之\u201c井中月\u201d——井中月者，月影也。月在天上，影在井中——月非井中物，然井中有月影。祖师西来意亦如是——西来意非言语可及，然言语中有西来意之影。如井中月——不可以手捞取，然可因影知有月。公案言语如井中月影——不可以言语为西来意，然可因言语知有西来意。曹山以\u201c井中月\u201d示学人：因指见月，不可以指为月。",
