    "answer": "面壁。",
    "context": "鲁祖宝云禅师见僧来，便面壁。僧无语。",
    "interpretation": "鲁祖面壁——见僧来便面壁——不以言语接引，以面壁为直指。面壁者，如达摩面壁——不以言语说，以默然为直指。鲁祖之面壁非不接引——乃以默然接引：道不在言语中，即此默然之当下。僧来欲求法——鲁祖面壁示之：法不在言语中，即此面壁之当下便是法。然僧无语——不能领会鲁祖之直指。",
