    "id": "koan-222",
    "question": "文殊师利白佛言：\u201c世尊，云何名一行三昧？\u201d佛言：\u201c法界一相，系缘法界，是名一行三昧。\u201d何谓一行三昧？",
    "answer": "一行三昧者，系心于一法界，不生分别。法界一相，即无相。于无相中系缘，即是一行。此为四祖道信念佛禅之所依。",
    "context": "《文殊说般若经》中佛为文殊说一行三昧，为禅宗念佛禅之教理依据。",
