    "id": "koan-223",
    "question": "问：\u201c既云无心，谁能说法？\u201d答：\u201c无心即是说法。若有心即不名说法。\u201d此段何意？",
    "answer": "无心即是说法——有心则有能所，能所对立则非真说法。无心说法，如空谷回声，如镜照物，应而无形。此示无心之妙用。",
    "context": "《无心论》以问答明无心之旨，无心非死寂，而是无住生心。",
