    "id": "koan-224",
    "question": "问：\u201c云何名观心？\u201d答：\u201c观心者，观自心也。自心本净，因境生念。但观此念起处，即见自心。\u201d此段何意？",
    "answer": "观心非观外境，而是观自心起念之处。念起即观，观即无念。于念起处见自心本净，即是观心。此为禅宗内观之根本法门。",
    "context": "《观心论》明观心之方法：观念起处，即见自心。",
