    "id": "koan-225",
    "question": "问：\u201c五行之中，何为究竟？\u201d答：\u201c五行皆方便，唯止观为究竟。前四门为助行，止观为正行。\u201d此段何意？",
    "answer": "施、戒、忍、进四门为助行，止观为正行。前四门积集福德资粮，止观开发智慧。福慧双修，方名究竟。此示禅宗止观并重之旨。",
    "context": "《五行论》明五种修行，以止观为根本。",
