    "id": "koan-227",
    "question": "问：\u201c无心与有心何异？\u201d答：\u201c无心即真心，有心即妄心。真心无心而无不知，妄心有心而全属分别。\u201d此段何意？",
    "answer": "真心无心——无妄念分别，而灵知不昧。妄心有心——有念有相，全属分别。无心非木石无知，而是无妄念之真心。此示真心与妄心之别。",
    "context": "《无心论》明无心即真心，有心即妄心。",
