    "question": "问：\u201c云何息诤？\u201d答：\u201c诤从分别起，无分别即无诤。但了诸法本空，诤自息灭。\u201d此段何意？",
    "answer": "诤论从分别心生——有分别则有是非，有是非则有诤。了达诸法本空，分别自灭，诤亦自息。此示无诤三昧之旨。",
