    "id": "koan-229",
    "question": "达摩大师说报冤行：\u201c修道人若受苦时，当自念言：我往昔无数劫中，弃本从末，流浪诸有，多起冤憎，违害无限。今虽无犯，是我宿殃，恶业果熟，非天非人所能见与，甘心忍受，都无冤诉。\u201d此何意？",
    "answer": "达摩四行之第一行——报冤行。受苦时不怨天尤人，了知皆是宿业果报，甘心忍受。此为修行之初门：于逆境中不起嗔心，即与道相应。",
    "context": "达摩大师《四行观》明四种修行：报冤行、随缘行、无所求行、称法行。",
