    "question": "问：\u201c方寸之间，有何物？\u201d答：\u201c方寸本无一物。若有一物，即非方寸。以无物故，能含万法。\u201d此段何意？",
    "answer": "方寸即心。心本无一物——若有物则非心。以无物故，能含万法——心如虚空，不碍万象。此示心性本空而能生万法之旨。",
    "context": "《方寸论》以\u201c方寸\u201d喻心，明心本空而含万法。",
