    "question": "五祖弘忍问：\u201c何名最上乘？\u201d答：\u201c最上乘者，即一心也。一心之外，更无别法。若离一心而求佛法，如缘木求鱼。\u201d此段何意？",
    "answer": "最上乘即一心——心外无法，法外无心。若离心求法，如缘木求鱼，永不可得。此示禅宗\u201c即心即佛\u201d之究竟旨。",
    "context": "五祖弘忍《最上乘论》明最上乘即一心。",
