    "question": "普照知讷《真心直说》曰：\u201c真心者，本来自性清净，不假修成，但离妄缘，即如如佛。\u201d此段何意？",
    "answer": "真心本自清净——非从修得。但离妄缘——去除妄念因缘。即如如佛——真心显现，本来是佛。此示禅宗\u201c本觉\u201d之旨：修行只是恢复本来，非从外得。",
