    "id": "koan-236",
    "question": "神会禅师问六祖：\u201c先佛后佛，无有异法，只传一乘。云何一乘？\u201d六祖曰：\u201c一乘者，即一心也。汝若悟一心，即名一乘。\u201d此段何意？",
    "answer": "一乘即一心——佛佛所传，唯传一心。悟一心即名一乘，非别有一乘可修。此示禅宗\u201c以心传心\u201d之究竟旨。",
