    "id": "koan-237",
    "question": "廓庵师远《十牛图》第七图\u201c忘牛存人\u201d颂曰：\u201c骑牛已得到家山，牛也空兮人也闲。红日三竿犹作梦，鞭绳空顿草堂间。\u201d此颂何意？",
    "answer": "忘牛存人——牛喻妄心，已驯伏故忘；人喻觉照，尚存故在。牛空人闲——妄心已息，觉照自在。此示修行至能所初忘之境界：妄心已伏，真心独存。",
    "context": "廓庵《十牛图》第七图\u201c忘牛存人\u201d，示妄心已伏、真心独存之境界。",
