    "id": "koan-238",
    "question": "洞山良价《宝镜三昧》曰：\u201c如临宝镜，形影相睹。汝不是渠，渠正是汝。\u201d此段何意？",
    "answer": "宝镜喻心。形影相睹——心与境相对，如形与影。汝不是渠——你不是境。渠正是汝——境即是心之显现。此示心境不二、能所一如之旨，为曹洞宗\u201c回互\u201d之根本施设。",
