    "interpretation": "法融此语不是否定修行，而是彻见本源后的如实语。心性本不生灭——你起心去\u201c知\u201d、起心去\u201c见\u201d，已是头上安头、妄上加妄。本来连一法都不存在，你还在那里讨论熏修炼习，岂非梦中说梦？此则公案须从\u201c无心绝观\u201d处会取：不是不修行，而是不立能修所修之相，但一切莫顾，安心无处，虚明自然现前。",
