    "answer": "诸佛体圆，更无增减，流入六道，处处皆圆，万类之中，个个是佛。譬如一团水银，分散诸处，颗颗皆圆，若不分时，只是一块，此一即一切，一切即一。",
    "interpretation": "黄檗以水银为喻，开示佛性在六道中各各皆圆。水银分散颗颗皆圆，喻佛性在万类中个个是佛；不分时只是一块，喻一即一切、一切即一。种种形貌如屋舍不同，皆是取舍所致，本源之性何得有别？此喻直指一多无碍、生佛平等之旨。",
