    "question": "赵州石桥度驴度马",
    "answer": "问：久响赵州石桥，到来只见掠彴子。赵州云：你只见掠彴子，不见赵州石桥？问：如何是赵州石桥？赵州云：过来过来。又问：如何是石桥？赵州云：度驴度马。",
    "context": "赵州以石桥接引学人",
    "interpretation": "学人只见掠彴子，不见赵州石桥。赵州云过来过来，令学人当下过来。再问石桥，答度驴度马——石桥之功用在度驴度马，佛法之功用在度一切众生。",
    "master": "赵州从谂",
