    "id": "koan-278",
    "question": "不名本寂",
    "answer": "不道。为什么不道？不名本寂。",
    "context": "洞山问曹山：阇黎名什么？答：本寂。洞山问：向上更道。答：不道。洞山问：为什么不道？答：不名本寂。洞山深器之。名字只是假名，本寂之性岂可以名相得之？一语双关，既答师问，又示本体不可说之旨。",
    "interpretation": "曹山与洞山的开场对话，是曹洞宗师徒开始的经典公案。本寂是名，不名本寂是道——名可以称呼，但真实的本寂之性超越名相，无法用语言表达。",
