    "question": "死猫儿头最贵",
    "answer": "死猫儿头最贵。为什么？无人著价。",
    "context": "僧问：世间什么物最贵？曹山答：死猫儿头最贵。僧问：为什么？曹山答：无人著价。无人著价之物方为最贵，喻佛法无可估量，亦喻彻底死尽偷心之人方为尊贵。",
    "interpretation": "死猫儿头是无人看重、无人出价之物，曹山以此喻佛法之尊贵——不可估量，不可比拟。亦喻彻底死尽偷心的修行者，无人珍视却最为尊贵。",
    "master": "曹山本寂",
    "source": "抚州曹山本寂禅师语录",
