    "question": "通身是病",
    "answer": "不医。教你求生不得，求死不得。",
    "context": "僧问：学人通身是病，请师医。曹山答：不医。僧问：为什么不医？曹山答：教你求生不得，求死不得。此病非色身之病，乃法身大病，非世医可治。不医者，令其超越生死两端，到无所求处。",
    "interpretation": "通身是病喻法身大病，攒簇不得。不医不是不治，而是令其超越生死两端——求生不得求死不得，到无所求处方见本分事。",
    "master": "曹山本寂",
