    "id": "koan-304",
    "question": "麻三斤（碧岩录第十二则）",
    "answer": "僧问洞山\u201c如何是佛\u201d，山云\u201c麻三斤\u201d。佛之一字，不可于言句上寻讨；洞山答处截断众流，麻三斤即佛、佛即麻三斤，直是难咬嚼、无尔下口处。若向句中觅，参到弥勒下生也未梦见在。",
    "master": "洞山守初",
