    "answer": "一击忘所知，更不假修治。",
    "context": "香严智闲在沩山灵祐处参禅，灵祐问其父母未生时面目，香严茫然无对。后于南阳忠国师遗址结庵居住，一日芟除草木，抛瓦击竹作声，忽然大悟。作偈曰：一击忘所知，更不假修治。动容扬古路，不堕悄然机。",
