    "question": "玄沙空印",
    "answer": "珠不自珠，见不自见。",
    "context": "惠洪觉范访玄沙师备遗迹，作真赞曰：\u201c备万物一体，宏机妙用，如以空印印于空文。是中无字可寻，无义可识，而能者得之。如以宝珠置于高显，有目者皆见。而珠不知自珠，见不自见。珠不自珠，见不自见，而我独见之，是谓妄见。我无妄见，而珠自圆。\u201d",
    "interpretation": "玄沙以\u201c空印印空文\u201d喻禅法：本无可印，亦无能印，一切现成。宝珠喻自性，见者自见——但珠不自知为珠，见亦不自知为见。若起\u201c我独见之\u201d一念，即是妄见。唯有能所双泯，珠自圆、法自全，方契玄沙宗旨。",
    "master": "玄沙师备",
    "source": "《林间录后集》·玄沙备禅师画像赞",
