    "interpretation": "永嘉玄觉阅维摩经发明心要，往曹溪印可，一宿即悟。惠洪赞其\u201c以槌授公，万象惊缩\u201d——六祖一槌击涂毒鼓，闻者僵仆；将此槌授与永嘉，则万象惊缩。喻永嘉得六祖心印后，机锋峻烈，一言半句令万象消殒。一宿觉之妙，在于情根无功、意识无作，现量圆成。",
