    "answer": "师才下座。九峰勤和尚把住云：\u201c今日喜遇同参。\u201d师云：\u201c同参底事作么生。\u201d峰云：\u201c九峰牵犁杨岐拽杷。\u201d师云：\u201c正当与么时，杨岐在前九峰在前。\u201d峰拟议。师托开云：\u201c将谓同参，元来不是。\u201d",
