    "question": "河里失钱河里摝",
    "master": "yangqi-fanghui",
    "source": "《杨岐方会和尚语录》",
    "answer": "上堂。身心清净诸境清净。诸境清净身心清净。还知云盖老人落地处么。乃云。河里失钱河里摝。",
    "interpretation": "在哪里丢了钱就在哪里捞，在哪里迷失就在哪里找回。直指当下，不离本处觅菩提。身心与诸境互为清净，迷悟不二。",
