    "answer": "师在慈明会里。一日提螺蛳一篮绕院云卖螺蛳。令众下语。皆不契。有一老宿揭帘见。以目顾视师。放身便卧。师放篮子便行。",
    "interpretation": "师以\u201c卖螺蛳\u201d试众，众皆不契。老宿不以言语回应，只以目顾视、放身便卧——无言即是。师放下篮子便行——以心传心，不立文字。",
