    "question": "道吾真掷杖收取",
    "master": "daowu-zhen",
    "source": "《杨岐方会和尚语录》",
    "answer": "上堂。众集。师以拄杖掷下来。随后跳下。众拟散。师乃召大众。众回首。师乃云。为老僧收取拄杖。便归方丈。",
