    "context": "僧问赵州狗子还有佛性也无，州云无。其僧复问蠢动含灵皆有佛性因甚狗子无佛性，州又云无。",
    "interpretation": "智彻禅师详析此公案：此僧当下若会得赵州开口处，唾面痛骂一场，赵州只得杜口无言。这僧不能领受，通身堕在疑情。疑情重时行也疑坐也疑着衣吃饭也疑，昼夜十二时无顷刻暂息。蓦然疑团子上爆地一声，彻见那边消息。",
