    "question": "如何是自家宝藏？",
    "answer": "只如今问者是。尔若回头，一切具足，受用不尽，更无欠少。",
    "context": "黄龙慧南举大珠参见马祖公案。祖问\u201c尔来作什么\u201d，珠云\u201c来求佛法\u201d。祖云\u201c尔为什么抛家失业，何不回头认取自家宝藏\u201d。珠云\u201c如何是自家宝藏\u201d。祖云\u201c只如今问者是，尔若回头一切具足受用不尽\u201d。师云：汝等诸人各有自家宝藏，为什么不得其用？只为不回头。",
