    "question": "有一人朝看华严暮看般若，有一人不参禅不论义，二人同到黄龙，安下那个即是？",
    "answer": "功德天黑暗女，有智主人二俱不受。",
    "context": "黄龙慧南禅师上堂云\u201c有一人朝看华严暮看般若昼夜精勤无有暂暇，有一人不参禅不论义把个破席日里睡。于此二人同到黄龙，一人有为一人无为，安下那个即是\u201d。良久云\u201c功德天黑暗女，有智主人二俱不受\u201d。执有为是妄，执无为亦非，有智主人二俱不受方是自在。",
