    "question": "旋岚偃岳而常静，江河竞注而不流",
    "answer": "僧肇《物不迁论》核心命题。狂风席卷山岳却恒常寂静，江河奔流不息却未曾流动——非谓万物静止不动，乃即动而见不迁。昔物自在昔，今物自在今，物不相往来。功业不可朽，故虽在昔而不化，不化故不迁。即万物之自虚而见动静不二之实相。",
