    "answer": "僧肇《涅槃无名论·妙存第七》引《庄子》语以明即真之境。玄道在于妙悟，妙悟在于即真，即真即有无齐观，齐观即彼己莫二。同我则非复有无，异我则乖于会通。不出不在而道存乎其间——物我冥一，怕尔无朕，乃曰涅槃。",
