    "answer": "洞山临终，弟子请留偈，洞山说：吾闲名已谢。众请不已，乃说偈：学者恒沙无一悟，过在寻他舌头路；欲得忘形泯踪迹，努力殷勤空里步。",
    "relatedBooks": ["dongshanyulu"]
