    "answer": "十牛图是宋代廓庵师远所作的十幅图，以牧牛比喻修行过程：寻牛、见迹、见牛、得牛、牧牛、骑牛归家、忘牛存人、人牛俱忘、返本还源、入廛垂手。描绘从迷失到彻悟再入世度人的完整历程。",
