    answer: '《坐禅仪》承天台智者大师《小止观》之统，都讲调身、调息、调心三大要。但《小止观》偏重止观双运的理路与次第，《坐禅仪》更简捷实用，归宗于禅门\u201c一切善恶都莫思量\u201d的无心要旨。宗赜也引用了圭峰宗密《修证仪》和《楞严经》中对治魔事的方法，可谓融天台、华严、禅门于一炉。',
