    "answer": "婆子以'蓦直去'接僧，僧才行，婆云'又这么去也'——意谓僧虽蓦直去，却落思量。赵州去问，婆子仍云'蓦直去'，赵州才行，婆云'又这么去也'。赵州便归云'婆子今日被老僧勘破了也'。赵州之勘破，在于他不落婆子圈套：婆子以'蓦直去'为玄妙，赵州以平常心行平常事，不被其语所转。",
