    "question": "僧肇是谁？他在佛教史上的地位如何？",
    "answer": "僧肇（384-414），京兆长安人，少年家贫以佣书为业，博览经史尤好老庄玄学。后读《维摩诘经》欢喜顶受而出家。师事鸠摩罗什于长安逍遥园，参与译经，被誉为\u201c解空第一\u201d。其主要著作《物不迁论》《不真空论》《般若无知论》《涅槃无名论》合称《肇论》，以龙树中观般若学为理论基础，融合中国本土的玄学思想，开创了中国佛教哲学的新境界，对后世三论宗、禅宗均有深远影响。",
